def gsl_bspline_wlssolve(x, y, weights=None):
    if len(x) != len(y):
        raise ValueError("Mismatched lengths of x and y")
    if weights is not None and len(weights) != len(x):
        raise ValueError("Mismatched lengths of weights")

    n = len(x)
    k = 3

    workspace = gsl_bspline_workspace.alloc(n, k)
    try:
        xvec = gsl_vector.alloc(n)
        yvec = gsl_vector.alloc(n)
        wvec = None
        if weights is not None:
            wvec = gsl_vector.alloc(n)
        for i in range(n):
            xvec.setitem(i,x[i])
            yvec.setitem(i,y[i])
            if weights is not None:
                wvec.setitem(i,weights[i])

        cvec = gsl_vector.alloc(4) # k + 1 coefficients
        sigma2 = ctypes.c_double(0.0)
        chi2 = ctypes.c_double(0.0)

        gsl_cblas.gsl_bspline_wlssolve(xvec, yvec, wvec, workspace, cvec, c_double(sigma2), c_double(chi2))
        coefficients = [cvec.getitem(i) for i in range(cvec.size)]
        chi_squared = chi2.value

        xvec.free()
        yvec.free()
        if wvec is not None:
            wvec.free()
        cvec.free()
    finally:
        gsl_bspline_workspace_free(workspace)

    return coefficients, chi_squared

